-- GENERATED by weave-cym-newydd-wrthyn-565.cjs — UNDO of stage 1 (and stage 2): restores every touched seed whole from the backup
\set ON_ERROR_STOP on
\if :{?finish}
\else
  \set finish ROLLBACK
\endif
BEGIN ISOLATION LEVEL REPEATABLE READ;
SET LOCAL statement_timeout = '20min';
DO $$ BEGIN IF to_regclass('backup_cym_newydd_wrthyn_565_seeds') IS NULL THEN RAISE EXCEPTION 'not applied (no backup_cym_newydd_wrthyn_565_seeds)'; END IF; END $$;
CREATE TEMP TABLE IF NOT EXISTS t_seeds (c text, s int, PRIMARY KEY (c, s));
TRUNCATE t_seeds; INSERT INTO t_seeds SELECT * FROM backup_cym_newydd_wrthyn_565_touched;
SET CONSTRAINTS ALL DEFERRED;  -- the debut guard judges the restored state, not the moment between delete and re-insert
SELECT count(*) AS locked_phrases FROM (SELECT 1 FROM course_practice_phrases x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number) FOR UPDATE OF x) z;
-- Restore every touched seed whole: phrases and LEGOs (and their intros/flags) deleted and re-inserted verbatim, seed rows set back.
DELETE FROM course_practice_phrases x USING t_seeds t WHERE (t.c, t.s) = (x.course_code, x.seed_number);
DELETE FROM lego_introductions x USING t_seeds t WHERE t.c = x.course_code AND substr(x.lego_id, 2, 4)::int = t.s;
DELETE FROM lego_proof_flags x USING t_seeds t WHERE t.c = x.course_code AND substr(x.lego_id, 2, 4)::int = t.s;
DELETE FROM course_legos x USING t_seeds t WHERE (t.c, t.s) = (x.course_code, x.seed_number);
INSERT INTO course_legos (id, course_code, seed_number, lego_index, type, is_new, known_text, target_text, components, status, release_batch, version, updated_at, created_at, known_audio_id, target1_audio_id, target2_audio_id, presentation_audio_id, target1_duration_ms, target2_duration_ms, target_text_roman, target_lego_id, known_gloss_segments, last_edit_event_id) SELECT id, course_code, seed_number, lego_index, type, is_new, known_text, target_text, components, status, release_batch, version, updated_at, created_at, known_audio_id, target1_audio_id, target2_audio_id, presentation_audio_id, target1_duration_ms, target2_duration_ms, target_text_roman, target_lego_id, known_gloss_segments, last_edit_event_id FROM backup_cym_newydd_wrthyn_565_legos;
INSERT INTO course_practice_phrases SELECT * FROM backup_cym_newydd_wrthyn_565_phrases;
INSERT INTO lego_introductions SELECT * FROM backup_cym_newydd_wrthyn_565_intros;
INSERT INTO lego_proof_flags SELECT * FROM backup_cym_newydd_wrthyn_565_flags;
DELETE FROM course_seed_weave_drops x USING t_seeds t WHERE (t.c, t.s) = (x.course_code, x.seed_number);
INSERT INTO course_seed_weave_drops SELECT * FROM backup_cym_newydd_wrthyn_565_drops;
UPDATE course_seeds x SET known_text = b.known_text, target_text = b.target_text, known_audio_id = b.known_audio_id, target1_audio_id = b.target1_audio_id,
  target2_audio_id = b.target2_audio_id, last_edit_event_id = b.last_edit_event_id FROM backup_cym_newydd_wrthyn_565_seeds b WHERE b.id = x.id;
SET CONSTRAINTS ALL IMMEDIATE;
DO $$ BEGIN
  IF (SELECT md5(string_agg(md5(row(x.id, x.known_text, x.target_text, x.known_audio_id, x.target1_audio_id, x.target2_audio_id)::text), '' ORDER BY x.id)) FROM course_seeds x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number)) IS DISTINCT FROM (SELECT md5(string_agg(md5(row(x.id, x.known_text, x.target_text, x.known_audio_id, x.target1_audio_id, x.target2_audio_id)::text), '' ORDER BY x.id)) FROM backup_cym_newydd_wrthyn_565_seeds x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number)) THEN RAISE EXCEPTION 'UNDO CHECK FAILED: seeds'; END IF;
  IF (SELECT md5(string_agg(md5(row(x.id, x.course_code, x.seed_number, x.lego_index, x.type, x.is_new, x.known_text, x.target_text, x.components, x.known_audio_id, x.target1_audio_id, x.target2_audio_id, x.presentation_audio_id)::text), '' ORDER BY x.id)) FROM course_legos x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number)) IS DISTINCT FROM (SELECT md5(string_agg(md5(row(x.id, x.course_code, x.seed_number, x.lego_index, x.type, x.is_new, x.known_text, x.target_text, x.components, x.known_audio_id, x.target1_audio_id, x.target2_audio_id, x.presentation_audio_id)::text), '' ORDER BY x.id)) FROM backup_cym_newydd_wrthyn_565_legos x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number)) THEN RAISE EXCEPTION 'UNDO CHECK FAILED: LEGOs'; END IF;
  IF (SELECT md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_practice_phrases x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number))
     IS DISTINCT FROM (SELECT md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM backup_cym_newydd_wrthyn_565_phrases x) THEN RAISE EXCEPTION 'UNDO CHECK FAILED: phrases'; END IF;
  RAISE NOTICE 'RESTORED: % seeds, % LEGOs, % phrases byte-identical to the backup', (SELECT count(*) FROM backup_cym_newydd_wrthyn_565_seeds), (SELECT count(*) FROM backup_cym_newydd_wrthyn_565_legos), (SELECT count(*) FROM backup_cym_newydd_wrthyn_565_phrases);
END $$;
DROP TABLE backup_cym_newydd_wrthyn_565_seeds, backup_cym_newydd_wrthyn_565_legos, backup_cym_newydd_wrthyn_565_phrases, backup_cym_newydd_wrthyn_565_intros, backup_cym_newydd_wrthyn_565_flags, backup_cym_newydd_wrthyn_565_touched, backup_cym_newydd_wrthyn_565_drops;

SELECT 'finishing with' k, :'finish' v;
:finish;
SELECT :'finish' = 'COMMIT' AS do_refresh \gset
\if :do_refresh
REFRESH MATERIALIZED VIEW CONCURRENTLY course_round_index;
\endif
